<script>
function openAppModal(){document.getElementById('appEditForm').reset();document.getElementById('app_id').value='';document.getElementById('appModalTitle').textContent='Nueva aplicación';document.getElementById('appModal').classList.add('open')}function editApp(app){openAppModal();document.getElementById('appModalTitle').textContent='Editar aplicación';document.getElementById('app_id').value=app.id;document.getElementById('app_name').value=app.name;document.getElementById('app_url').value=app.url;document.getElementById('app_category').value=app.category;document.getElementById('app_description').value=app.description;document.getElementById('app_is_active').value=app.is_active}function closeAppModal(){document.getElementById('appModal').classList.remove('open')}document.getElementById('appModal').addEventListener('click',e=>{if(e.target.id==='appModal')closeAppModal()});
</script>
